import { motion } from "framer-motion";
import {
  ArrowRight, ArrowUpRight, Github, Linkedin, Mail, MapPin, Code2, Database,
  Braces, GitBranch, Terminal, Sparkles, ExternalLink, Trophy, GraduationCap,
  Users, Send, Zap, Activity, Layers, Server, Package, Shield, Coffee, Star, Award,
  Briefcase, Calendar, ChevronRight, Copy, Check, Building2
} from "lucide-react";
import { useState } from "react";
import SpaceScene from "../components/SpaceScene";
import Navbar from "../components/Navbar";
import { Counter, Typewriter, ScrollProgress, GlowCursor, Tilt } from "../components/UIBits";

/* ================= DATA ================= */
const SKILLS = [
  { icon: Code2, name: "Languages", accent: "from-amber-500/20 to-orange-500/5", items: [
    { n: "JavaScript / TypeScript", lvl: 95 },
    { n: "C / C++", lvl: 85 },
    { n: "Python", lvl: 80 },
    { n: "SQL", lvl: 85 },
    { n: "Rust", lvl: 60 },
    { n: "Solidity", lvl: 70 },
  ]},
  { icon: Braces, name: "Frontend", accent: "from-sky-500/20 to-cyan-500/5", items: [
    { n: "React.js", lvl: 95 },
    { n: "Next.js", lvl: 85 },
    { n: "Redux / Zustand", lvl: 85 },
    { n: "Tailwind CSS", lvl: 92 },
    { n: "Three.js / R3F", lvl: 75 },
    { n: "Responsive Design", lvl: 92 },
  ]},
  { icon: Server, name: "Backend", accent: "from-emerald-500/20 to-teal-500/5", items: [
    { n: "Node.js", lvl: 90 },
    { n: "Express.js", lvl: 88 },
    { n: "REST APIs", lvl: 90 },
    { n: "Prisma ORM", lvl: 80 },
    { n: "Microservices", lvl: 72 },
  ]},
  { icon: Database, name: "Databases", accent: "from-violet-500/20 to-purple-500/5", items: [
    { n: "PostgreSQL", lvl: 90 },
    { n: "MongoDB", lvl: 85 },
    { n: "MySQL", lvl: 78 },
    { n: "Schema Design", lvl: 82 },
  ]},
  { icon: GitBranch, name: "Tools & DevOps", accent: "from-rose-500/20 to-pink-500/5", items: [
    { n: "Git / GitHub", lvl: 95 },
    { n: "Docker", lvl: 78 },
    { n: "CI/CD", lvl: 75 },
    { n: "Jest / Mocha", lvl: 80 },
    { n: "Linux", lvl: 82 },
  ]},
  { icon: Terminal, name: "Blockchain / AI · Secondary", accent: "from-yellow-500/20 to-amber-500/5", items: [
    { n: "Solidity + Hardhat", lvl: 72 },
    { n: "Web3.js / Ethers", lvl: 75 },
    { n: "Anchor · Solana", lvl: 68 },
    { n: "Chainlink", lvl: 60 },
    { n: "LangChain / RAG", lvl: 65 },
  ]},
];

const EXPERIENCE = [
  {
    company: "Dabur India Ltd",
    role: "Software Engineering Intern",
    duration: "May 2026 — Present",
    location: "India · On-site",
    stack: ["Node.js", "React", "Python", "REST", "Docker"],
    bullets: [
      "Shipping performance & feature improvements on DaburGPT, an internal AI platform used by product & marketing teams.",
      "Owning latency reduction work across Node/React/Python services — profiling, indexing and caching hot paths.",
      "Contributing to test coverage and internal tech docs to keep a distributed engineering team unblocked.",
    ],
  },
  {
    company: "Zerone Smart Infrastructure Pvt Ltd",
    role: "Frontend Developer Intern",
    duration: "Jun 2024 — Aug 2024",
    location: "Remote",
    stack: ["React", "Redux", "Custom Hooks", "Agile"],
    bullets: [
      "Architected mobile-first React + Redux UI components — reduced average load time by ~20% across 5+ apps.",
      "Designed a reusable component library w/ custom hooks — accelerated feature delivery by 30% for 3 partner teams.",
      "Owned Zedyer sprints in Agile/Scrum; consistent green sprints with disciplined Git workflows.",
    ],
  },
];

const PROJECTS = [
  {
    name: "TestiView",
    tag: "Full-Stack SaaS",
    role: "Design · Backend · Frontend",
    stack: ["React", "Node", "Express", "PostgreSQL", "JWT", "Prisma"],
    desc: "A testimonial collection SaaS. REST API with input-validation middleware, JWT auth, and PostgreSQL data model. Responsive React front-end shipped with grid, carousel & animated displays.",
    metrics: [
      { k: "Integration time", v: "-50%" },
      { k: "Retention", v: "+25%" },
      { k: "Live users", v: "100+" },
    ],
    image: "https://images.unsplash.com/photo-1551288049-bebda4e38f71?crop=entropy&cs=srgb&fm=jpg&ixid=M3w3NDk1ODB8MHwxfHNlYXJjaHwxfHxtb2Rlcm4lMjBkYXJrJTIwZGFzaGJvYXJkJTIwdWl8ZW58MHx8fHwxNzgzMTQ0OTQ1fDA&ixlib=rb-4.1.0&q=85&w=1200",
    live: "#",
    code: "https://github.com/Vansh98789",
  },
  {
    name: "EventFlex",
    tag: "Blockchain × Frontend",
    role: "Smart Contracts · dApp",
    stack: ["React", "Solidity", "Web3.js", "Ethereum", "Hardhat"],
    desc: "Trustless event management dApp. Solidity contracts handle on-chain ticket verification & automated escrow. React + Web3.js frontend with MetaMask flow, QR check-ins and on-chain logging.",
    metrics: [
      { k: "Txn errors", v: "-80%" },
      { k: "Beta users", v: "50+" },
      { k: "Check-in speed", v: "3× faster" },
    ],
    image: "https://images.unsplash.com/photo-1763718528755-4bca23f82ac3?crop=entropy&cs=srgb&fm=jpg&ixid=M3w3NDk1ODB8MHwyfHxtb2Rlcm4lMjBkYXJrJTIwZGFzaGJvYXJkJTIwdWl8ZW58MHx8fHwxNzgzMTQ0OTQ1fDA&ixlib=rb-4.1.0&q=85&w=1200",
    live: "#",
    code: "https://github.com/Vansh98789",
  },
  {
    name: "TimeVault",
    tag: "Decentralized dApp",
    role: "Rust · Anchor · Full-stack",
    stack: ["React", "Rust", "Anchor", "Solana", "IPFS", "Filebase"],
    desc: "Timestamp-locked capsules on Solana Devnet using Anchor PDAs; IPFS via Filebase keeps large payloads off-chain. Wallet-based auth via Phantom / Backpack for a fully censorship-resistant flow.",
    metrics: [
      { k: "On-chain cost", v: "-90%" },
      { k: "Wallet auth", v: "100%" },
      { k: "Uptime target", v: "24/7" },
    ],
    image: "https://images.unsplash.com/photo-1619262105903-c65a6396c72f?crop=entropy&cs=srgb&fm=jpg&ixid=M3w3NDk1ODB8MHwzfHxtb2Rlcm4lMjBkYXJrJTIwZGFzaGJvYXJkJTIwdWl8ZW58MHx8fHwxNzgzMTQ0OTQ1fDA&ixlib=rb-4.1.0&q=85&w=1200",
    live: "#",
    code: "https://github.com/Vansh98789",
  },
];

const ACHIEVEMENTS = [
  { metric: 50, suffix: "%", label: "Faster integration", desc: "TestiView REST API cut client integration time." },
  { metric: 80, suffix: "%", label: "Fewer txn errors", desc: "EventFlex blockchain escrow eliminated 4/5 failures." },
  { metric: 90, suffix: "%", label: "Cheaper storage", desc: "TimeVault IPFS/Filebase pipeline vs. pure on-chain." },
  { metric: 30, suffix: "%", label: "Faster delivery", desc: "Reusable component library at Zerone across 3 teams." },
];

const STATS = [
  { icon: Zap, num: 2, suffix: "+", label: "Years shipping" },
  { icon: Package, num: 15, suffix: "+", label: "Projects built" },
  { icon: Users, num: 250, suffix: "+", label: "Students mentored" },
  { icon: Coffee, num: 8.5, dec: 1, suffix: "", label: "CGPA · MAIT" },
];

const LEADERSHIP = [
  {
    org: "Computer Society of India, MAIT",
    role: "Technical Coordinator",
    duration: "Feb 2024 — Present",
    points: [
      "Led 3 hackathons with 100+ participants across CS & allied streams.",
      "Ran 5 technical workshops on AI/ML, Blockchain, Cloud for 150+ students — 40% engagement lift.",
      "Collaborated with 15+ core team members to streamline event logistics.",
    ],
  },
  {
    org: "Refine Consulting Society, MAIT",
    role: "Senior Executive",
    duration: "Dec 2023 — Present",
    points: [
      "Organised 4 case-study competitions with cross-college participation.",
      "Mentored 15+ juniors on Porter's Five Forces & SWOT frameworks.",
      "Data-driven promotion strategy: +25% participation, +35% satisfaction.",
    ],
  },
];

const PILLARS = [
  {
    icon: Layers,
    title: "Full-stack systems",
    desc: "From Postgres schema to pixel — designing REST APIs, modelling data, and delivering responsive React UIs.",
  },
  {
    icon: Activity,
    title: "Performance obsession",
    desc: "Profiling hot paths, cutting bundle size, caching smartly — proven 20-50% wins on real production traffic.",
  },
  {
    icon: Shield,
    title: "Ships reliably",
    desc: "Tests, code review, CI/CD and clear documentation — I optimise for the team that ships tomorrow's version.",
  },
];

/* ================= HELPERS ================= */
const Section = ({ id, overline, title, subtitle, children, className = "" }) => (
  <section id={id} data-testid={`section-${id}`} className={`relative py-24 sm:py-32 px-6 md:px-10 ${className}`}>
    <div className="mx-auto max-w-7xl">
      {overline && (
        <motion.div
          initial={{ opacity: 0, x: -10 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="text-xs font-mono tracking-[0.3em] uppercase text-[#F4B961] mb-4 flex items-center gap-3"
        >
          <span className="inline-block w-8 h-px bg-[#F4B961]" />
          {overline}
        </motion.div>
      )}
      {title && (
        <motion.h2
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="font-display text-3xl sm:text-4xl lg:text-5xl tracking-tight text-white/95 mb-3 max-w-4xl"
        >
          {title}
        </motion.h2>
      )}
      {subtitle && (
        <motion.p
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6, delay: 0.1 }}
          className="text-white/60 max-w-2xl text-base sm:text-lg leading-relaxed mb-14"
        >
          {subtitle}
        </motion.p>
      )}
      {children}
    </div>
  </section>
);

const fadeUp = {
  initial: { opacity: 0, y: 24 },
  whileInView: { opacity: 1, y: 0 },
  viewport: { once: true, amount: 0.2 },
  transition: { duration: 0.7, ease: [0.22, 1, 0.36, 1] },
};

/* ================= SECTIONS ================= */
function Hero() {
  return (
    <section id="top" data-testid="section-hero" className="relative min-h-screen flex items-center px-6 md:px-10 pt-32 pb-16">
      <div className="mx-auto max-w-7xl w-full grid md:grid-cols-12 gap-8 items-center">
        <div className="md:col-span-7 relative z-10">
          <motion.div {...fadeUp} className="text-xs font-mono tracking-[0.3em] uppercase text-[#F4B961] mb-6 flex items-center gap-2">
            <span className="inline-block w-8 h-px bg-[#F4B961]" />
            SYSTEM ONLINE // DEV PROTOCOL v2.6
          </motion.div>

          <motion.h1
            {...fadeUp}
            transition={{ ...fadeUp.transition, delay: 0.1 }}
            className="font-display text-5xl sm:text-6xl lg:text-[88px] leading-[0.92] tracking-tight text-white"
          >
            Vansh
            <br />
            <span className="text-[#F4B961]">Maheshwari</span>
            <span className="text-[#F4B961]">.</span>
          </motion.h1>

          <motion.div
            {...fadeUp}
            transition={{ ...fadeUp.transition, delay: 0.15 }}
            className="mt-5 h-8 text-lg sm:text-xl text-white/85"
          >
            <Typewriter phrases={[
              "Software Development Engineer.",
              "Full-stack builder — React · Node · Postgres.",
              "Performance-obsessed. Ship-first mindset.",
              "Occasional blockchain & AI explorer."
            ]} />
          </motion.div>

          <motion.p
            {...fadeUp}
            transition={{ ...fadeUp.transition, delay: 0.25 }}
            className="mt-6 text-base sm:text-lg text-white/60 max-w-xl leading-relaxed"
          >
            Final-year CS student at MAIT · SWE intern @ Dabur India. I design REST APIs, ship performant React interfaces, and care about
            <span className="text-white/85"> systems that don't wake you at 3 AM</span>.
          </motion.p>

          <motion.div
            {...fadeUp}
            transition={{ ...fadeUp.transition, delay: 0.35 }}
            className="mt-10 flex flex-wrap items-center gap-4"
          >
            <a href="#projects" data-testid="hero-cta-work" className="group inline-flex items-center gap-2 px-6 py-3.5 rounded-full bg-[#F4B961] text-[#030305] font-medium hover:bg-[#E89D42] transition-all hover:-translate-y-0.5 shadow-[0_0_0_1px_rgba(244,185,97,0.2),0_15px_40px_-10px_rgba(244,185,97,0.4)]">
              Explore Work
              <ArrowRight size={16} className="transition-transform group-hover:translate-x-1" />
            </a>
            <a href="https://github.com/Vansh98789" target="_blank" rel="noreferrer" data-testid="hero-cta-github" className="inline-flex items-center gap-2 px-6 py-3.5 rounded-full border border-white/15 text-white hover:bg-white/5 hover:border-white/30 transition-all backdrop-blur-md">
              <Github size={16} /> View GitHub
            </a>
            <a href="#contact" data-testid="hero-cta-contact" className="text-sm text-white/60 hover:text-[#F4B961] transition-colors underline underline-offset-4 decoration-white/20">
              or say hi ↗
            </a>
          </motion.div>

          <motion.div {...fadeUp} transition={{ ...fadeUp.transition, delay: 0.45 }} className="mt-16 grid grid-cols-2 sm:grid-cols-4 gap-4 max-w-2xl">
            {STATS.map((s, i) => {
              const Icon = s.icon;
              return (
                <div key={i} className="glass rounded-xl p-4" data-testid={`hero-stat-${i}`}>
                  <Icon size={16} className="text-[#F4B961] mb-2" />
                  <div className="font-display text-2xl text-white">
                    <Counter end={s.num} suffix={s.suffix} decimals={s.dec || 0} />
                  </div>
                  <div className="text-[10px] font-mono uppercase tracking-widest text-white/40 mt-1">{s.label}</div>
                </div>
              );
            })}
          </motion.div>
        </div>

        {/* Floating code terminal card — sits in space beside the moon */}
        <div className="md:col-span-5 relative min-h-[520px] hidden md:block">
          <motion.div
            initial={{ opacity: 0, y: 40 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.9, delay: 0.6 }}
            className="absolute right-0 top-24 w-full max-w-md animate-float"
          >
            <div className="glass rounded-2xl overflow-hidden shadow-[0_25px_60px_-15px_rgba(0,0,0,0.6)] backdrop-blur-2xl">
              <div className="flex items-center gap-2 px-4 py-3 border-b border-white/5">
                <span className="w-2.5 h-2.5 rounded-full bg-[#EF4444]/70" />
                <span className="w-2.5 h-2.5 rounded-full bg-[#F4B961]/70" />
                <span className="w-2.5 h-2.5 rounded-full bg-emerald-400/70" />
                <span className="ml-3 text-[10px] font-mono uppercase tracking-widest text-white/40">~/vansh — intro.ts</span>
              </div>
              <pre className="text-[12.5px] leading-6 p-5 font-mono text-white/80 overflow-x-auto">
{`const vansh = {
  role: `}<span className="text-[#F4B961]">"SDE"</span>{`,
  stack: [`}<span className="text-emerald-300">"React"</span>{`, `}<span className="text-emerald-300">"Node"</span>{`, `}<span className="text-emerald-300">"Postgres"</span>{`],
  currently: `}<span className="text-[#F4B961]">"@Dabur · DaburGPT"</span>{`,
  believes: (
    ship: `}<span className="text-sky-300">"fast"</span>{`,
    read: `}<span className="text-sky-300">"prod logs"</span>{`,
    write: `}<span className="text-sky-300">"tests"</span>{`
  ),
  side: [`}<span className="text-violet-300">"blockchain"</span>{`, `}<span className="text-violet-300">"AI"</span>{`],
  open_to: `}<span className="text-[#F4B961]">"SDE roles 2026"</span>{`,
};`}
              </pre>
              <div className="flex items-center gap-2 px-5 py-3 border-t border-white/5 text-[10px] font-mono uppercase tracking-widest text-white/40">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
                available for opportunities
              </div>
            </div>
          </motion.div>
        </div>
      </div>

      {/* Scroll cue */}
      <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex flex-col items-center gap-2 text-white/40 text-[10px] font-mono tracking-[0.3em]">
        <span>SCROLL DOWN</span>
        <span className="w-px h-8 bg-gradient-to-b from-[#F4B961] to-transparent" />
      </div>
    </section>
  );
}

function Pillars() {
  return (
    <Section id="pillars" overline="// 01 · What I Bring" title="Three things I optimise for." subtitle="The lens I use whether the ticket says 'SDE', 'Frontend', or 'Full-stack'.">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
        {PILLARS.map((p, i) => {
          const Icon = p.icon;
          return (
            <Tilt key={p.title} className="h-full">
              <motion.div
                {...fadeUp}
                transition={{ ...fadeUp.transition, delay: i * 0.1 }}
                className="glass rounded-2xl p-7 h-full relative overflow-hidden group"
                data-testid={`pillar-${i}`}
              >
                <div className="absolute -top-16 -right-16 w-40 h-40 rounded-full bg-[#F4B961]/5 blur-3xl group-hover:bg-[#F4B961]/10 transition-colors" />
                <div className="relative">
                  <div className="w-11 h-11 rounded-xl bg-[#F4B961]/10 border border-[#F4B961]/25 flex items-center justify-center mb-5">
                    <Icon size={18} className="text-[#F4B961]" />
                  </div>
                  <h3 className="font-display text-xl text-white mb-2">{p.title}</h3>
                  <p className="text-sm text-white/60 leading-relaxed">{p.desc}</p>
                  <div className="mt-6 text-[10px] font-mono uppercase tracking-widest text-white/30 flex items-center gap-1">
                    0{i + 1} <ChevronRight size={12} />
                  </div>
                </div>
              </motion.div>
            </Tilt>
          );
        })}
      </div>
    </Section>
  );
}

function About() {
  return (
    <Section id="about" overline="// 02 · About" title="Engineer first. Explorer always.">
      <div className="grid md:grid-cols-12 gap-6">
        <motion.div {...fadeUp} className="md:col-span-7 glass rounded-2xl p-8 sm:p-10 relative overflow-hidden">
          <div className="absolute top-0 right-0 w-64 h-64 bg-[#F4B961]/5 blur-3xl rounded-full" />
          <div className="relative">
            <p className="text-white/85 text-lg leading-relaxed">
              I'm a <span className="text-[#F4B961]">Software Development Engineer</span> in the final year of B.Tech CSE at Maharaja Agrasen Institute of Technology, Delhi — currently interning at <span className="text-white">Dabur India Ltd</span> on their internal AI platform, DaburGPT.
            </p>
            <p className="text-white/60 leading-relaxed mt-5">
              My core craft is <span className="text-white/90">full-stack engineering</span>: designing REST APIs, building responsive React interfaces, modelling relational data, and shipping features that measurably move product metrics. I care deeply about performance, clean architecture, and code that the next developer can read.
            </p>
            <p className="text-white/60 leading-relaxed mt-5">
              On the side I explore <span className="text-white/85">blockchain</span> (Solidity, Anchor/Solana) and <span className="text-white/85">AI tooling</span> — but my compass points firmly at strong SDE fundamentals: systems thinking, data structures, and reliable software.
            </p>

            <div className="mt-8 flex flex-wrap gap-3">
              <span className="px-3 py-1.5 rounded-full text-xs font-mono bg-[#F4B961]/10 border border-[#F4B961]/25 text-[#F4B961]">Available · SDE Roles 2026</span>
              <span className="px-3 py-1.5 rounded-full text-xs font-mono bg-white/[0.04] border border-white/10 text-white/70">Based in Delhi, IN</span>
              <span className="px-3 py-1.5 rounded-full text-xs font-mono bg-white/[0.04] border border-white/10 text-white/70">Open to Remote</span>
            </div>
          </div>
        </motion.div>

        <motion.div {...fadeUp} transition={{ ...fadeUp.transition, delay: 0.15 }} className="md:col-span-5 flex flex-col gap-4">
          <div className="glass rounded-2xl p-6 flex items-start gap-4">
            <div className="w-10 h-10 rounded-lg bg-emerald-500/10 border border-emerald-500/25 flex items-center justify-center shrink-0">
              <Briefcase size={16} className="text-emerald-300"/>
            </div>
            <div>
              <div className="text-xs font-mono uppercase tracking-widest text-emerald-300/80 mb-1">Now</div>
              <div className="text-white/95 font-medium">SWE Intern @ Dabur India</div>
              <div className="text-white/50 text-sm mt-1">Optimising Node/React/Python services on DaburGPT.</div>
            </div>
          </div>
          <div className="glass rounded-2xl p-6 flex items-start gap-4">
            <div className="w-10 h-10 rounded-lg bg-[#F4B961]/10 border border-[#F4B961]/25 flex items-center justify-center shrink-0">
              <Star size={16} className="text-[#F4B961]"/>
            </div>
            <div>
              <div className="text-xs font-mono uppercase tracking-widest text-[#F4B961]/90 mb-1">Focus</div>
              <div className="text-white/95 font-medium">Full-stack SDE · Systems · Performance</div>
              <div className="text-white/50 text-sm mt-1">React · Node · PostgreSQL · Docker · CI/CD.</div>
            </div>
          </div>
          <div className="glass rounded-2xl p-6 flex items-start gap-4">
            <div className="w-10 h-10 rounded-lg bg-violet-500/10 border border-violet-500/25 flex items-center justify-center shrink-0">
              <Sparkles size={16} className="text-violet-300"/>
            </div>
            <div>
              <div className="text-xs font-mono uppercase tracking-widest text-violet-300/80 mb-1">Also Into</div>
              <div className="text-white/95 font-medium">3D Web · Blockchain · AI Tools</div>
              <div className="text-white/50 text-sm mt-1">Three.js / R3F · Solidity · Anchor · LangChain.</div>
            </div>
          </div>
        </motion.div>
      </div>
    </Section>
  );
}

function Skills() {
